"import React, { useState, useEffect } from 'react';
import { X, Save, MapPin, UserCheck, MinusCircle, AlertCircle, ArrowRight } from 'lucide-react';

const ReduceStockModal = ({ show, item, onClose, onConfirm }) => {
  const [reduceAmount, setReduceAmount] = useState(1);
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (item) {
      setReduceAmount(1);
      setLocation(item.location || '');
      setNotes(item.notes || '');
    }
  }, [item, show]);

  if (!show || !item) return null;

  const currentQty = parseInt(item.qty, 10) || 0;
  const safeReduceAmount = Math.max(1, Math.min(currentQty, parseInt(reduceAmount, 10) || 1));
  const resultingQty = Math.max(0, currentQty - safeReduceAmount);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (currentQty <= 0) return;

    onConfirm({
      id: item.id,
      reduceAmount: safeReduceAmount,
      newQty: resultingQty,
      location: location.trim(),
      notes: notes.trim(),
      itemName: item.name
    });
  };

  return (
    <div className="modal-overlay active">
      <div className="modal-box reduce-stock-modal" style={{ maxWidth: '520px' }}>
        <div className="modal-header">
