"node -e '
const testCases = [
  "PALLAZO (43), KLAIM HP (2), SERVICE (17)",
  "Pallazo (6), Demo IT Talk: SMG (1), SBY (1)",
  "Pallazo (21), Demo Pegadaian (1), IT Talk JKT (1), IT Talk SMG (1)",
  "STOCK JKT: PALLAZO (16)",
  "STOCK DEMO: IT TALK AMBAS (1)",
  "IT TALK SBY (1), IT TALK AMBAS (1), SERVICE (1)",
  "Gudang Stok Lama"
];

function parseBreakdown(locStr, totalQty) {
  let pallazo = 0, surabaya = 0, ambassador = 0, demo = 0, service = 0, klaimDoa = 0;
  let otherParts = [];

  const regex = /([^,()]+?)\s*\(\s*(\d+)\s*\)/g;
  let match, foundAny = false;

  while ((match = regex.exec(locStr)) !== null) {
    foundAny = true;
    const label = match[1].trim();
    const count = parseInt(match[2], 10) || 0;
    const lower = label.toLowerCase();

    if (lower.includes("klaim") || lower.includes("doa")) {
      klaimDoa += count;
    } else if (lower.includes("service")) {
      service += count;
    } else if (lower.includes("demo")) {
      demo += count;
    } else if (lower.includes("sby") || lower.includes("surabaya")) {
      surabaya += count;
    } else if (lower.includes("ambas")) {
      ambassador += count;
    } else if (lower.includes("pallazo") || lower.includes("jkt")) {
      pallazo += count;
    } else {
      otherParts.push({ label, count });
    }
  }

  if (!foundAny) {
    const lower = locStr.toLowerCase();
    if (lower.includes("surabaya") || lower.includes("sby")) surabaya = totalQty;
    else if (lower.includes("ambas")) ambassador = totalQty;
    else pallazo = totalQty;
  }

  return { pallazo, surabaya, ambassador, demo, service, klaimDoa, otherParts };
}

testCases.forEach(str => {
  console.log("IN:", str);
  console.log("OUT:", parseBreakdown(str, 10));
  console.log("---");
});
