function buildLocationString(breakdown, isSpecialPart) {
  const parts = [];
  if (isSpecialPart) {
    if (breakdown.pallazo > 0) parts.push(`PALLAZO (${breakdown.pallazo})`);
    if (breakdown.demo > 0) parts.push(`DEMO (${breakdown.demo})`);
    if (breakdown.klaimDoa > 0) parts.push(`KLAIM HP (${breakdown.klaimDoa})`);
    if (breakdown.service > 0) parts.push(`SERVICE (${breakdown.service})`);
  } else {
    if (breakdown.pallazo > 0) parts.push(`PALLAZO (${breakdown.pallazo})`);
    if (breakdown.surabaya > 0) parts.push(`IT TALK SBY (${breakdown.surabaya})`);
    if (breakdown.ambassador > 0) parts.push(`IT TALK AMBAS (${breakdown.ambassador})`);
    if (breakdown.demo > 0) parts.push(`DEMO (${breakdown.demo})`);
    if (breakdown.service > 0) parts.push(`SERVICE (${breakdown.service})`);
  }
  if (parts.length === 0) return "Habis (0)";
  return parts.join(", ");
}

// Test initial 365K5PA
