"node -e '
function decrementLocation(locStr, targetName, reduceAmount, totalQty) {
  if (!locStr) return { updated: `${targetName} (${Math.max(0, totalQty - reduceAmount)})`, currentCount: totalQty, newCount: Math.max(0, totalQty - reduceAmount) };

  const getMatcher = (target) => {
    const t = target.toLowerCase();
    if (t.includes("pallazo") || t === "plz") return /(pallazo|plz)[^\d(]*\((\d+)\)/i;
    if (t.includes("surabaya") || t === "sby") return /(?:it talk\s+)?(sby|surabaya)[^\d(]*\((\d+)\)/i;
    if (t.includes("semarang") || t === "smg") return /(?:it talk\s+)?(smg|semarang)[^\d(]*\((\d+)\)/i;
    if (t.includes("ambas") || t.includes("ambassador")) return /(?:it talk\s+)?(ambas|ambassador)[^\d(]*\((\d+)\)/i;
    if (t.includes("jkt") || t.includes("jakarta")) return /(?:it talk\s+)?(jkt|jakarta)[^\d(]*\((\d+)\)/i;
    if (t.includes("demo")) return /(demo[^\d(]*)\((\d+)\)/i;
    if (t.includes("service")) return /(service[s]?[^\d(]*)\((\d+)\)/i;
    if (t.includes("klaim") || t.includes("doa")) return /(klaim[^\d(]*)\((\d+)\)/i;
    return new RegExp(`(${target}[^\\d(]*)\\(([\\d]+)\\)`, "i");
  };

  const matcher = getMatcher(targetName);
  const match = locStr.match(matcher);

  if (match) {
    const currentCount = parseInt(match[match.length - 1], 10);
    const newCount = Math.max(0, currentCount - reduceAmount);
    const updated = locStr.replace(matcher, (full) => {
      return full.replace(`(${currentCount})`, `(${newCount})`);
    });
    return { updated, currentCount, newCount };
  }

  // If no parenthesized count for target found, check if single location
  const resultingTotal = Math.max(0, totalQty - reduceAmount);
  if (resultingTotal === 0) {
    return { updated: `Habis (0) - Terakhir di ${targetName}`, currentCount: totalQty, newCount: 0 };
  }
  return { updated: `${targetName} (${resultingTotal})`, currentCount: totalQty, newCount: resultingTotal };
}

